import type { TextInput } from './editor/text-input.ts';
import { Editor } from './editor/draft.ts';
import type { Scope, PreviewResult } from './generated-contracts.ts';
import type { Preference } from './preferences.ts';
import type { PreviewBackground } from './preview-preferences.ts';
import type { Language, LocalizedText } from './i18n/index.ts';
import type { MessageSlot } from './i18n/messages.ts';

export type InputMode = (
  | { kind: 'search'; scope: Scope; original: string; selected: string }
  | { kind: 'category'; scope: Scope; selected: string }
  | { kind: 'field'; key: string; buffer: string; original?: string }
  | { kind: 'path'; action: 'import' | 'export'; buffer: string }
  | { kind: 'numeric'; field: 'padding' | 'refresh_interval' }
) & { edit?: TextInput } | null;

export interface View {
  language?: Language;
  localized?: Partial<Record<MessageSlot, LocalizedText>>;
  previewBackground?: PreviewBackground;
  editor: Editor | null;
  input: InputMode;
  preview: PreviewResult | null;
  preferences: Preference[];
  preferencesError: string;
  error: string;
  previewError: string;
  previewBusy: boolean;
  message: string;
  busy: string;
  uncertain: boolean;
}

type EditorData = Pick<
  Editor,
  | 'description'
  | 'baseline'
  | 'draft'
  | 'page'
  | 'advanced'
  | 'adding'
  | 'pickerSaved'
  | 'detail'
  | 'guidanceScroll'
  | 'explanation'
  | 'quick'
  | 'review'
  | 'preset'
  | 'path'
  | 'pendingTransfer'
  | 'setting'
  | 'activeNumeric'
  | 'selected'
  | 'order'
  | 'search'
  | 'category'
  | 'buffers'
  | 'fieldErrors'
  | 'fieldErrorMessages'
>;
export interface ClientProps {
  epoch: number;
  ack: number;
  generation: number;
  columns: number;
  rows: number;
  view: Omit<View, 'editor'> & { editor: EditorData | null };
}

export function clientProps(
  view: View,
  epoch: number,
  ack: number,
  generation: number,
  columns: number,
  rows: number,
): ClientProps {
  const e = view.editor;
  // The host freezes port data recursively. Never expose live editor arrays or
  // preference rows: subsequent keys must still mutate our own draft.
  return JSON.parse(
    JSON.stringify({
      epoch,
      ack,
      generation,
      columns,
      rows,
      view: {
        ...view,
        editor: e
          ? {
              description: e.description,
              baseline: e.baseline,
              draft: e.draft,
              page: e.page,
              advanced: e.advanced,
              adding: e.adding,
              pickerSaved: e.pickerSaved,
              detail: e.detail, preset: e.preset, path: e.path, pendingTransfer: e.pendingTransfer,
              guidanceScroll: e.guidanceScroll,
              review: e.review, quick: e.quick, explanation:e.explanation,
              setting: e.setting,
              activeNumeric: e.activeNumeric,
              selected: e.selected,
              order: e.order,
              search: e.search,
              category: e.category,
              buffers: e.buffers,
              fieldErrors: e.fieldErrors,
              fieldErrorMessages: e.fieldErrorMessages,
            }
          : null,
      },
    }),
  ) as ClientProps;
}

/** Rendering uses the same editor model, with only plain data crossing ports. */
export function clientView(props: ClientProps): View {
  const data = props.view.editor;
  return {
    ...props.view,
    editor: data
      ? Object.assign(new Editor(data.description, data.baseline), data)
      : null,
  };
}

