    text: string;
}>(spans: T[]): T[] {
    const result: T[] = [];
    for (const span of spans) {
        const previous = result.at(-1);
        const keys = Object.keys(span).filter(key => key !== 'text') as (keyof T)[];
        if (previous && Object.keys(previous).length === Object.keys(span).length && keys.every(key => previous[key] === span[key]))
            previous.text += span.text;
        else
